/* ProtectionPro — VectorPDF: SVG pages into a jsPDF document as vector graphics.
 *
 * svg2pdf.js (js/lib/svg2pdf.umd.min.js) and the subset Liberation fonts
 * (js/lib/pdf-fonts.js, GENERATED by testing/pdf-fonts/build_pdf_fonts.py) load
 * on first use. Text keeps its characters (Ω, Δ, ×, ≤ …) and stays searchable.
 * `inlineStyles` writes each element's computed style onto it, so a diagram
 * clone renders the same with no stylesheet; `draw` maps the diagram's fonts to
 * the embedded ones (anything monospace → PPMono, the rest → PPSans) and falls
 * back to a picture of the page if svg2pdf fails.
 */

const VectorPDF = {
  _loading: null,

  _script(src) {
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = () => reject(new Error('Could not load ' + src));
      document.head.appendChild(s);
    });
  },

  ensure() {
    if (window.svg2pdf && window.PDF_FONTS) return Promise.resolve();
    if (!this._loading) {
      const v = typeof APP_VERSION !== 'undefined' ? APP_VERSION : '';
      this._loading = Promise.all([
        window.svg2pdf ? null : this._script(`js/lib/svg2pdf.umd.min.js?v=${v}`),
        window.PDF_FONTS ? null : this._script(`js/lib/pdf-fonts.js?v=${v}`),
      ]).catch((e) => { this._loading = null; throw e; });
    }
    return this._loading;
  },

  registerFonts(doc) {
    const F = window.PDF_FONTS || {};
    for (const [key, b64] of Object.entries(F)) {
      const [family, style] = key.split('-');
      doc.addFileToVFS(key + '.ttf', b64);
      doc.addFont(key + '.ttf', family, style);
    }
  },

  PROPS: ['fill', 'fill-opacity', 'stroke', 'stroke-width', 'stroke-dasharray', 'stroke-opacity', 'stroke-linecap',
    'stroke-linejoin', 'opacity', 'font-family', 'font-size', 'font-weight', 'font-style', 'text-anchor'],

  // Computed style → presentation attributes, then drop the <style> elements.
  // The clone is attached off-screen while it is measured.
  inlineStyles(svg) {
    const host = document.createElement('div');
    host.setAttribute('style', 'position:absolute;left:-100000px;top:0;width:10px;height:10px;overflow:hidden;opacity:0;pointer-events:none');
    host.appendChild(svg);
    document.body.appendChild(host);
    try {
      const els = svg.querySelectorAll('*');
      const gone = [];
      for (const el of els) {
        const tag = el.tagName.toLowerCase();
        if (tag === 'style' || tag === 'title' || tag === 'desc') continue;
        const cs = getComputedStyle(el);
        if (cs.display === 'none') { gone.push(el); continue; }
        if (cs.visibility === 'hidden') el.setAttribute('visibility', 'hidden');
        for (const p of this.PROPS) {
          let v = cs.getPropertyValue(p);
          if (!v) continue;
          if (p === 'stroke-width' || p === 'font-size') v = String(parseFloat(v));
          else if (p === 'stroke-dasharray') v = v === 'none' ? 'none' : v.replace(/px/g, '').replace(/,/g, ' ');
          else if (p === 'font-weight') v = (+v >= 600 || v === 'bold') ? 'bold' : 'normal';
          el.setAttribute(p, v);
        }
        if (el.hasAttribute('style')) el.removeAttribute('style');
      }
      gone.forEach(el => el.remove());
      svg.querySelectorAll('style').forEach(s => s.remove());
    } finally {
      host.remove();
    }
    return svg;
  },

  _mapFonts(svg) {
    svg.querySelectorAll('text, tspan').forEach(t => {
      const fam = (t.getAttribute('font-family') || '').toLowerCase();
      if (!fam && t.tagName.toLowerCase() === 'tspan') return;
      t.setAttribute('font-family', /mono|courier|consol|menlo/.test(fam) ? 'PPMono' : 'PPSans');
      // labels inside a symbol inherit its line stroke; svg2pdf would paint
      // that as a block, so text is filled only
      t.setAttribute('stroke', 'none');
      const w = t.getAttribute('font-weight');
      if (w && w !== 'bold' && w !== 'normal') t.setAttribute('font-weight', +w >= 600 ? 'bold' : 'normal');
    });
    const root = svg;
    if (!root.getAttribute('font-family')) root.setAttribute('font-family', 'PPSans');
  },

  // Draw one page; resolves true for vector, false when it fell back to a picture
  async draw(doc, svgEl, w, h) {
    const svg = svgEl.cloneNode(true);
    this._mapFonts(svg);
    const host = document.createElement('div');
    host.setAttribute('style', 'position:absolute;left:-100000px;top:0;opacity:0;pointer-events:none');
    host.appendChild(svg);
    document.body.appendChild(host);
    try {
      await doc.svg(svg, { x: 0, y: 0, width: w, height: h });
      return true;
    } catch (e) {
      console.warn('Vector PDF failed, using a picture of the page:', e);
      const scale = Math.min(6, 5000 / w);
      const canvas = await this.raster(svgEl, w, h, scale);
      doc.addImage(canvas.toDataURL('image/jpeg', 0.92), 'JPEG', 0, 0, w, h);
      return false;
    } finally {
      host.remove();
    }
  },

  raster(svgEl, w, h, scale) {
    const svg = svgEl.cloneNode(true);
    svg.setAttribute('width', w * scale);
    svg.setAttribute('height', h * scale);
    return new Promise(res => Project._rasterizeSVG(svg, w, h, scale, (canvas) => res(canvas)));
  },
};
